package com.ridelink.farepayment.config; import org.springframework.amqp.core.*; import org.springframework.context.annotation.*; @Configuration public class RabbitConfig {@Bean TopicExchange paymentExchange(){return new TopicExchange("ridelink.payment");}@Bean Queue paymentRecordedQueue(){return new Queue("ridelink.payment-recorded",true);}@Bean Binding paymentBinding(){return BindingBuilder.bind(paymentRecordedQueue()).to(paymentExchange()).with("payment.recorded");}}
